            Anim->SetPosition(.3f,false);SetEntityAnimation(TEXT("player:local"),TEXT("idle"));Check(FMath::IsNearlyEqual(Anim->GetCurrentTime(),.3f),TEXT("sit transition does not restart on status snapshots"));
