            Cast->SetNumberField(TEXT("age_ms"),0);Vitals->SetNumberField(TEXT("health_pct"),0);SetEntityAnimation(TEXT("player:local"),TEXT("idle"));Check(AnimationStates.FindRef(TEXT("player:local"))==TEXT("death"),TEXT("casting never overrides corpse animation"));Vitals->SetNumberField(TEXT("health_pct"),100);Row->RemoveField(TEXT("spell_cast"));SetEntityAnimation(TEXT("player:local"),TEXT("idle"));

